/*
 * COMPOSITION: A dark stage plane (7x6 @ z=-2.5) graded with the app's ink
 *   gradient sits behind a centered row of three machined-metal cards
 *   (1.5w x 1.9h, gap 0.25, row 5.0w) — left/right cards flank a slightly
 *   proud center card (the focal panel). Each card carries a brushed metal
 *   icon-seat disc + accent numeral, a serif title, and a mono body line,
 *   all on the 0.25 baseline grid, with a soft radial contact shadow below.
 * LIGHT RIG: node-local key (#fff6ec 2.6 upper-right-front), fill (#e8ecf2
 *   0.7 upper-left), rim (#ffffff 1.5 back-left, capped per doctrine), plus
 *   a 0.18 ambient floor — key sits upper-left-ish so lifted cards read a
 *   bright top bevel + darker bottom edge, selling the physical hover lift.
 * MATERIAL STRATEGY: card bodies are extruded rounded-rect MeshPhysicalNode
 *   slabs (roughness 0.6, metalness 0.25, clearcoat 0.15) with a vertical
 *   two-stop ink gradient baked via TSL position-based mix, a thin LineLoop
 *   hairline border, and a brushed cylindrical icon-seat disc (metalness
 *   0.5, roughness 0.55, clearcoat 0.2, anisotropy 0.6) carrying an
 *   accent-emissive numeral glyph — the single brightest element.
 * MOTION: stagger-cards mount (fade-up, y +0.2 -> 0, opacity 0 -> 1, 0.5s
 *   power2.out, 80ms stagger) + per-card hover lift (y +0.06 / z +0.12,
 *   180ms power2.out, disc emissive 1.6 -> 2.2, contact shadow widens and
 *   softens) driven from userData.handlers.
 * FOCAL ELEMENT: the center card's icon-seat disc + accent numeral glyph —
 *   the only saturated red in frame, sitting slightly proud of its siblings.
 */

import {
  MeshPhysicalNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import { color, mix, uv, positionLocal, smoothstep, uniform, length, vec2 } from 'three/tsl';
import { gsap } from 'gsap';

const CARD_TEXTS = [
  { glyph: '01', title: 'In-House Calibre', body: 'Every movement is designed, machined, and finished under one roof.' },
  { glyph: '02', title: 'Five-Year Guarantee', body: 'Each piece is serviced free of charge for five years from delivery.' },
  { glyph: '03', title: 'Hand-Finished Dials', body: 'Guilloche cut on a 1912 rose engine, one dial at a time.' },
];

function roundedRectShape(THREE, w, h, r) {
  const shape = new THREE.Shape();
  const x = -w / 2, y = -h / 2;
  shape.moveTo(x + r, y);
  shape.lineTo(x + w - r, y);
  shape.quadraticCurveTo(x + w, y, x + w, y + r);
  shape.lineTo(x + w, y + h - r);
  shape.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  shape.lineTo(x + r, y + h);
  shape.quadraticCurveTo(x, y + h, x, y + h - r);
  shape.lineTo(x, y + r);
  shape.quadraticCurveTo(x, y, x + r, y);
  return shape;
}

function buildBackdrop(THREE, colors) {
  const geo = new THREE.PlaneGeometry(7, 6);
  const mat = new MeshBasicNodeMaterial();
  const top = color(colors.gradientStops[0].hex);
  const bottom = color(colors.gradientStops[1].hex);
  const grad = mix(top, bottom, uv().y);
  // subtle radial glow behind the focal center card, kept low-alpha so
  // the accent stays <=10% of the frame per palette discipline.
  const centered = uv().sub(vec2(0.5, 0.42));
  const dist = length(centered);
  const glow = smoothstep(0.55, 0.0, dist).mul(0.06);
  mat.colorNode = grad.add(color(colors.accent).mul(glow));
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.set(0, 0, -2.5);
  return { mesh, geo, mat };
}

function buildLights(THREE, group) {
  const disposables = [];
  const ambient = new THREE.AmbientLight(0xffffff, 0.18);
  group.add(ambient);
  disposables.push(ambient);

  const key = new THREE.DirectionalLight(0xfff6ec, 2.6);
  key.position.set(2.4, 2.8, 2.2);
  key.target.position.set(0, 0.4, 0);
  group.add(key, key.target);
  disposables.push(key, key.target);

  const fill = new THREE.DirectionalLight(0xe8ecf2, 0.7);
  fill.position.set(-2.6, 1.2, 1.8);
  fill.target.position.set(0, 0.4, 0);
  group.add(fill, fill.target);
  disposables.push(fill, fill.target);

  const rim = new THREE.DirectionalLight(0xffffff, 1.5);
  rim.position.set(-1.2, 2.2, -2.6);
  rim.target.position.set(0, 0.6, 0);
  group.add(rim, rim.target);
  disposables.push(rim, rim.target);

  return disposables;
}

function buildCard(ctx, colors, textItem, index, isFocal) {
  const THREE = ctx.THREE;
  const cardW = 1.5, cardH = 1.9, cardDepth = 0.06, r = 0.06;

  const disposables = [];
  const card = new THREE.Group();

  // card body -----------------------------------------------------------
  const shape = roundedRectShape(THREE, cardW, cardH, r);
  const geo = new THREE.ExtrudeGeometry(shape, {
    depth: cardDepth,
    bevelEnabled: true,
    bevelThickness: 0.008,
    bevelSize: 0.008,
    bevelSegments: 2,
    steps: 1,
  });
  geo.translate(0, 0, -cardDepth / 2);

  const mat = new MeshPhysicalNodeMaterial();
  const t = positionLocal.y.div(cardH).add(0.5).clamp(0, 1);
  mat.colorNode = mix(color(colors.gradientStops[0].hex), color(colors.gradientStops[1].hex), t);
  mat.roughness = 0.6;
  mat.metalness = 0.25;
  mat.clearcoat = 0.15;
  mat.clearcoatRoughness = 0.4;

  const cardMesh = new THREE.Mesh(geo, mat);
  card.add(cardMesh);
  disposables.push(geo, mat);

  // hairline border -------------------------------------------------------
  const borderShape = roundedRectShape(THREE, cardW + 0.006, cardH + 0.006, r + 0.003);
  const pts2 = borderShape.getPoints(32);
  const pts3 = pts2.map((p) => new THREE.Vector3(p.x, p.y, cardDepth / 2 + 0.002));
  const borderGeo = new THREE.BufferGeometry().setFromPoints(pts3);
  const borderMat = new THREE.LineBasicMaterial({ color: 0x26262f });
  const border = new THREE.LineLoop(borderGeo, borderMat);
  card.add(border);
  disposables.push(borderGeo, borderMat);

  // icon seat disc ---------------------------------------------------------
  const iconSeatY = 0.55;
  const discGeo = new THREE.CylinderGeometry(0.2, 0.2, 0.05, 32, 1);
  discGeo.rotateX(Math.PI / 2);
  const discMat = new MeshPhysicalNodeMaterial();
  discMat.color = new THREE.Color(0x2a2a33);
  discMat.metalness = 0.5;
  discMat.roughness = 0.55;
  discMat.clearcoat = 0.2;
  discMat.clearcoatRoughness = 0.3;
  discMat.emissive = new THREE.Color(colors.accent);
  discMat.emissiveIntensity = isFocal ? 1.8 : 1.6;
  if ('anisotropy' in discMat) discMat.anisotropy = 0.6;
  const disc = new THREE.Mesh(discGeo, discMat);
  disc.position.set(0, iconSeatY, cardDepth / 2 + 0.025);
  card.add(disc);
  disposables.push(discGeo, discMat);

  // glyph ------------------------------------------------------------------
  const glyph = ctx.fontAtlas.createText(textItem.glyph, {
    fontSize: 20,
    color: colors.accent,
    align: 'center',
  });
  glyph.position.set(0, iconSeatY, cardDepth / 2 + 0.05);
  card.add(glyph);

  // title -------------------------------------------------------------------
  const title = ctx.fontAtlas.createText(textItem.title, {
    fontSize: 20,
    color: colors.paper,
    align: 'left',
  });
  title.position.set(-cardW / 2 + 0.375, 0.05, cardDepth / 2 + 0.03);
  card.add(title);

  // body --------------------------------------------------------------------
  const body = ctx.fontAtlas.
